class Counter {
    int count = 0;
    void up() { count++; }
}
public class Main {
    public static void main(String[] args) {
        Counter a = new Counter();
        Counter b = new Counter();
        a.up();
        a.up();
        b.up();
        System.out.println(a.count + b.count);
    }
}

class Counter {
